INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (425236, 16519, 'South China Morning Post', 'en', 'Nepal army races to rescue 100 trapped in hydropower tunnel after flash floods', 'https://www.scmp.com/news/asia/south-asia/article/3365555/nepal-army-races-rescue-100-trapped-hydropower-tunnel-after-flash-floods', 'Helicopter rescue teams were working on Friday to rescue around 100 people trapped inside a tunnel at a hydropower project in Nepal swamped by a devastating flood two days earlier. “Our focus is in search and rescue of people … some people are trapped in the tunnel of Trishuli 3A hydropower project,” Nepal Army spokesman Raja Ram Basnet said. “Two helicopters have been dispatched but it is challenging because it is tough to even locate the entry points of the tunnel. Relief efforts are also...', 'https://cdn.i-scmp.com/sites/default/files/styles/1280x720/public/d8/images/canvas/2026/08/28/418ed970-7bf8-46ab-9e1e-c9a4df7f65c2_737b3301.jpg?itok=-zc9aMbu&v=1787898205', '2026-08-28T06:23:35+00:00', '2026-08-28T12:53:51.835325'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (425250, 16519, 'South China Morning Post', 'en', 'China-Nepal floods: debris lake the size of 1,000 Olympic pools in breach danger', 'https://www.scmp.com/news/china/politics/article/3365529/china-nepal-disaster-death-toll-nears-500-lake-overflow-threatens-rescue-work', 'The death toll from catastrophic flash floods and mudslides at the Gyirong Port border crossing between China and Nepal continued to rise on Friday, as concerns grew that a lake formed from the debris could breach, triggering further flooding. As of Friday afternoon, five people were confirmed dead and 558 missing on the Chinese side of the border, with 469 dead and nearly 1,000 missing in Nepal. The tragedy unfolded on Wednesday morning when a massive Himalayan landslide triggered a...', 'https://cdn.i-scmp.com/sites/default/files/styles/1280x720/public/d8/images/canvas/2026/08/28/160f5690-6fcd-4b5d-bd2f-292e5379f360_2ab28ebe.jpg?itok=TLvLK2yr&v=1787891545', '2026-08-28T03:51:41+00:00', '2026-08-28T12:53:51.979239'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
